"""Blob storage abstraction.

Stage 5 ships the local-disk backend. Stage 7 adds an S3-compatible adapter
behind the same small interface.
"""

from __future__ import annotations

from pathlib import Path, PurePosixPath


class StorageError(Exception):
    """A blob could not be stored or read."""


class LocalBlobStorage:
    """Store blobs under a fixed root using server-generated keys."""

    def __init__(self, root: Path | str) -> None:
        self.root = Path(root)

    def _path(self, key: str) -> Path:
        # Keys are generated by the server, but validate anyway so a future
        # caller cannot turn a key into path traversal.
        relative = PurePosixPath(key)
        if relative.is_absolute() or ".." in relative.parts or not relative.parts:
            raise StorageError("invalid storage key")
        return self.root.joinpath(*relative.parts)

    def save(self, key: str, data: bytes) -> str:
        path = self._path(key)
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            temporary = path.with_suffix(path.suffix + ".tmp")
            temporary.write_bytes(data)
            temporary.replace(path)
        except OSError as exc:  # pragma: no cover - filesystem failure
            raise StorageError("could not store blob") from exc
        return key

    def read(self, key: str) -> bytes:
        path = self._path(key)
        try:
            return path.read_bytes()
        except OSError as exc:
            raise StorageError("blob not found") from exc

    def delete(self, key: str) -> None:
        path = self._path(key)
        try:
            path.unlink(missing_ok=True)
        except OSError as exc:  # pragma: no cover - filesystem failure
            raise StorageError("could not delete blob") from exc

    def exists(self, key: str) -> bool:
        return self._path(key).is_file()

    def path_for(self, key: str) -> Path:
        return self._path(key)
